(function(root){'use strict';
const core=root.KANA_META_CORE,repos=root.KANA_DATA.repositories,cloud=root.KANA_CLOUD.sync;let state=repos.settings.getMetaSystems(core.emptyState())||core.emptyState(),syncTimer=null,bossTurn=0,bossHits=0;
const main=document.querySelector('main'),home=document.querySelector('#home'),study=document.querySelector('#studyLink'),back=document.querySelector('#back'),header=document.querySelector('.header-actions');
const profileButton=document.createElement('button');profileButton.className='study-link';profileButton.type='button';profileButton.textContent='Perfil';header.insertBefore(profileButton,study);
const style=document.createElement('style');style.textContent=`
.meta-screen{align-self:start;padding-top:12px}.meta-screen h1{font-size:clamp(2.7rem,10vw,5rem);margin:8px 0 10px}.profile-grid{display:grid;gap:9px;margin:24px 0}.profile-row{display:grid;grid-template-columns:110px 1fr 40px;align-items:center;gap:10px;font-weight:800;font-size:.86rem}.profile-track{height:8px;border-radius:99px;background:#252529;overflow:hidden}.profile-track i{display:block;height:100%;background:var(--green);border-radius:inherit}.meta-panels{display:grid;gap:12px}.meta-panel{border:1px solid var(--line);border-radius:17px;background:var(--panel);padding:17px}.meta-panel h2{font-size:1rem;margin:0 0 10px}.meta-panel p{color:var(--muted);line-height:1.5;margin:4px 0}.meta-list{display:grid;gap:8px}.meta-item{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid var(--line)}.meta-item:first-child{border-top:0}.meta-item b{font-family:"Noto Sans JP","Yu Gothic",sans-serif}.curse{color:#d7a7ff}.nemesis{color:var(--red)}.boss-card{width:100%;border:1px solid #775c36;border-radius:17px;background:linear-gradient(135deg,#241d14,#171719);color:var(--ink);padding:18px;text-align:left;font:inherit;cursor:pointer}.boss-card:disabled{opacity:.55;cursor:not-allowed}.boss-card strong{display:block;font-size:1.2rem}.boss-play{text-align:center;padding-top:10vh}.boss-glyph{font-family:"Noto Sans JP","Yu Gothic",sans-serif;font-size:clamp(2.4rem,12vw,5.5rem);margin:30px 0 12px}.boss-choices{display:grid;gap:9px}.boss-choices button{min-height:52px;border:1px solid var(--line);border-radius:14px;background:var(--panel);color:var(--ink);font:inherit;font-weight:800;padding:12px}.boss-result{font-size:clamp(4rem,20vw,8rem);font-weight:950}@media(max-width:430px){.header-actions{gap:3px}.header-actions .study-link{padding:8px 5px;font-size:.72rem}}@media(min-width:650px){.meta-panels{grid-template-columns:1fr 1fr}.boss-choices{grid-template-columns:repeat(3,1fr)}}`;document.head.append(style);
const screen=document.createElement('section');screen.className='screen meta-screen';screen.hidden=true;screen.innerHTML='<p class="eyebrow">perfil global</p><h1>Seu japonês no かな。</h1><p class="intro">Métricas internas do treino. Não são uma promessa de fluência.</p><div id="profileGrid" class="profile-grid"></div><div class="meta-panels"><section class="meta-panel"><h2>Dependência de português</h2><div id="dependencyValue" class="boss-result" style="font-size:3rem"></div><p id="dependencyCopy"></p></section><section class="meta-panel"><h2>Boss</h2><button id="bossCard" class="boss-card" type="button"></button></section><section class="meta-panel"><h2>☠ Amaldiçoados</h2><div id="cursedList" class="meta-list"></div></section><section class="meta-panel"><h2>NEMESIS</h2><div id="nemesisList" class="meta-list"></div></section><section class="meta-panel" style="grid-column:1/-1"><h2>墓地 · Cemitério</h2><div id="cemeteryList" class="meta-list"></div></section></div>';
const boss=document.createElement('section');boss.className='screen meta-screen boss-play';boss.hidden=true;boss.innerHTML='<p class="eyebrow">boss · 境界</p><div id="bossProgress"></div><div id="bossGlyph" class="boss-glyph"></div><p id="bossQuestion" class="intro"></p><button id="bossAudio" class="challenge-start" type="button" hidden>▶ ouvir</button><div id="bossChoices" class="boss-choices"></div><p id="bossFeedback" class="feedback"></p><div id="bossEnd" hidden><strong id="bossScore" class="boss-result"></strong><h1 id="bossTitle"></h1><p id="bossCopy" class="intro"></p><button id="bossRetry" class="challenge-start" type="button">TENTAR NOVAMENTE</button></div>';
main.append(screen,boss);const $=id=>document.getElementById(id);
function save(){repos.settings.saveMetaSystems(state);clearTimeout(syncTimer);syncTimer=setTimeout(()=>cloud.enqueueSnapshot('meta-systems',state),350);}
function profile(){return core.profile(state,repos.mastery.getSkills(),repos.mastery.getVocabulary());}
function render(){const data=profile(),labels={hiragana:'HIRAGANA',katakana:'KATAKANA',kanji:'KANJI',vocabulary:'VOCABULÁRIO',grammar:'GRAMÁTICA',listening:'ESCUTA',reading:'LEITURA'},grid=$('profileGrid');grid.textContent='';for(const [key,label]of Object.entries(labels)){const value=data[key],row=document.createElement('div');row.className='profile-row';row.innerHTML=`<span>${label}</span><div class="profile-track"><i style="width:${value??0}%"></i></div><b>${value==null?'—':value}</b>`;grid.append(row);}const dep=data.portugueseDependency;$('dependencyValue').textContent=dep.value==null?'—':`${dep.value}%`;$('dependencyCopy').textContent=dep.value==null?'Ainda não há exercícios suficientes resolvidos sem português.':`${dep.evidence} respostas diretas avaliadas. Quanto menor, menos apoio foi necessário.`;renderList($('cursedList'),data.cursed.slice(0,8),item=>`<div class="meta-item curse"><b>${item.display}</b><span>${item.errors}/${item.attempts} erros</span></div>`,'Nenhum item amaldiçoado.');renderList($('nemesisList'),data.nemeses.slice(0,8),item=>`<div class="meta-item nemesis"><b>${item.display}</b><span>${item.runDeaths} mortes</span></div>`,'Nenhuma Nemesis.');renderList($('cemeteryList'),data.cemetery.slice(0,12),item=>`<div class="meta-item"><span><b>${item.display}</b><small style="display:block;color:var(--muted)">${item.mode.toUpperCase()} · encerrou em ${item.longestRun}</small></span><span>MORTES: ${item.deaths}</span></div>`,'O Cemitério ainda está vazio.');const metrics=core.bossMetrics(state,repos.mastery.getSkills(),repos.mastery.getVocabulary()),record=state.bosses?.boundary||{};$('bossCard').disabled=!metrics.unlocked;$('bossCard').innerHTML=metrics.unlocked?`<strong>境界 · BOUNDARY</strong><span>${record.completedAt?'DERROTADO':'7 habilidades. Exija 6.'} · recorde ${record.best||0}/7</span>`:`<strong>🔒 境界</strong><span>${Math.min(metrics.attempts,100)} / 100 tentativas · ${Math.min(metrics.territories,3)} / 3 territórios</span>`;}
function renderList(node,items,template,empty){node.innerHTML=items.length?items.map(template).join(''):`<p>${empty}</p>`;}
function show(){for(const node of main.children)node.hidden=true;screen.hidden=false;home.hidden=true;study.hidden=true;profileButton.hidden=true;back.hidden=false;render();window.scrollTo({top:0,behavior:'smooth'});}
function close(){screen.hidden=true;boss.hidden=true;home.hidden=false;study.hidden=false;profileButton.hidden=false;back.hidden=true;}
function startBoss(){bossTurn=0;bossHits=0;screen.hidden=true;boss.hidden=false;$('bossEnd').hidden=true;$('bossChoices').hidden=false;nextBoss();}
function nextBoss(){if(bossTurn>=core.BOUNDARY.length){finishBoss();return;}const item=core.BOUNDARY[bossTurn];$('bossProgress').textContent=`SELO ${bossTurn+1} / 7 · ${item.territory.toUpperCase()}`;$('bossGlyph').textContent=item.audio?'':item.prompt;$('bossQuestion').textContent=item.question;$('bossFeedback').textContent='';$('bossAudio').hidden=!item.audio;if(item.audio){$('bossAudio').onclick=()=>root.KANA_AUDIO_PROVIDER?.play(item.prompt,{rate:1});setTimeout(()=>$('bossAudio').click(),180);}const choices=$('bossChoices');choices.textContent='';item.choices.slice().sort(()=>Math.random()-.5).forEach(value=>{const button=document.createElement('button');button.textContent=value;button.onclick=()=>{const correct=value===item.answer;if(correct)bossHits++;button.classList.add(correct?'correct':'wrong');choices.querySelectorAll('button').forEach(b=>b.disabled=true);$('bossFeedback').textContent=correct?'SELO ROMPIDO':`Resposta: ${item.answer}`;bossTurn++;setTimeout(nextBoss,correct?520:900);};choices.append(button);});}
function finishBoss(){state=core.finishBoss(state,bossHits,Date.now());save();$('bossChoices').hidden=true;$('bossAudio').hidden=true;$('bossGlyph').textContent='';$('bossQuestion').textContent='';$('bossEnd').hidden=false;$('bossScore').textContent=`${bossHits}/7`;$('bossTitle').textContent=bossHits>=6?'BOSS DERROTADO':'A FRONTEIRA RESISTIU';$('bossCopy').textContent=bossHits>=6?'Sete habilidades pressionadas. Seis selos ou mais foram rompidos.':'Volte quando a fraqueza tiver mudado.';$('bossRetry').onclick=startBoss;}
function prioritize(items,mode,previous){const cursed=items.filter(item=>{const id=Array.isArray(item)?item[0]:item.id;return state.items[`${mode}:${id}`]?.cursed&&id!==previous;});if(cursed.length&&Math.random()<.16)return cursed[Math.floor(Math.random()*cursed.length)];return null;}
profileButton.addEventListener('click',show);$('bossCard').addEventListener('click',startBoss);back.addEventListener('click',event=>{if(screen.hidden&&boss.hidden)return;event.preventDefault();event.stopImmediatePropagation();close();});
addEventListener('kana:attempt-recorded',event=>{state=core.recordAttempt(state,event.detail);save();});addEventListener('kana:run-ended',event=>{if(!root.KANA_CLOUD.auth.current?.user?.id)return;state=core.recordDeath(state,event.detail);save();});addEventListener('kana:remote-restored',()=>{state=repos.settings.getMetaSystems(core.emptyState())||core.emptyState();});
root.KANA_META={show,isCursed:(mode,id)=>Boolean(state.items?.[`${mode}:${id}`]?.cursed),prioritize,getState:()=>JSON.parse(JSON.stringify(state)),commit:next=>{state=next;save();return JSON.parse(JSON.stringify(state));},profile:()=>JSON.parse(JSON.stringify(profile()))};
})(window);
